) THEN #{row.adminOnlyEditInfo} ELSE admin_only_edit_info END, admin_only_edit_info_source = CASE WHEN #{row.adminOnlyEditInfoObservedAt} IS NOT NULL AND (#{row.adminOnlyEditInfoObservedAt}, #{row.sourceRank}) > (COALESCE(admin_only_edit_info_observed_at, -1),
