) THEN #{row.adminOnlyEditInfoObservedAt} ELSE admin_only_edit_info_observed_at END,
member_add_mode = CASE WHEN #{row.memberAddModeObservedAt} IS NOT NULL AND (#{row.memberAddModeObservedAt}, #{row.sourceRank}) > (COALESCE(member_add_mode_observed_at, -1),
) THEN #{row.memberAddMode} ELSE member_add_mode END, member_add_mode_source = CASE WHEN #{row.memberAddModeObservedAt} IS NOT NULL AND (#{row.memberAddModeObservedAt}, #{row.sourceRank}) > (COALESCE(member_add_mode_observed_at, -1),
) THEN #{row.memberAddModeSource} ELSE member_add_mode_source END, member_add_mode_observed_at = CASE WHEN #{row.memberAddModeObservedAt} IS NOT NULL AND (#{row.memberAddModeObservedAt}, #{row.sourceRank}) > (COALESCE(member_add_mode_observed_at, -1),
